import java.util.ArrayList;
import java.util.List;

public class Drill {
    static String csv(List<String> parts) {
        StringBuilder sb = new StringBuilder();
        for (String p : parts) {
            sb.append(p).append(',');
        }
        sb.deleteCharAt(sb.length() - 1);
        return sb.toString();
    }
    static String bracket(String s) {
        StringBuilder sb = new StringBuilder(s);
        sb.insert(0, '[');
        sb.append(']');
        int n = sb.length();
        return sb.toString() + n;
    }
    static List<String> chunks(String s) {
        List<String> out = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == ',') {
                out.add(sb.toString());
                @@BLANK@@
            } else {
                sb.append(c);
            }
        }
        out.add(sb.toString());
        return out;
    }
    static String rev(String s) {
        return new StringBuilder(s).reverse().toString();
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(csv(List.of("a", "b", "c")), "a,b,c");
        check(bracket("ab"), "[ab]4");
        check(chunks("a,bc,d"), "[a, bc, d]");
        check(rev("abc"), "cba");
        done();
    }
}
